export default function MenuCard({ item, cart, addToCart, removeFromCart }) {

  const cartItem = cart.find(i => i.id === item.id);
  const quantity = cartItem ? cartItem.quantity : 0;

  const isOutOfStock = item.stock === 0;
  const isTopRated = item.avg_rating >= 4.5;
  const isPopular = item.sold_count >= 10;

  return (
    <div className="menu-card">

      <div className="badges">
        {isPopular && <span className="badge popular">🔥 Popular</span>}
        {isTopRated && <span className="badge rated">⭐ Top Rated</span>}
      </div>

      <h4>{item.name}</h4>
      <p className="price">₹{item.price}</p>

      <div className="rating">
        ⭐ {item.avg_rating} | Sold: {item.sold_count}
      </div>

      <div className="stock">Stock: {item.stock}</div>

      {isOutOfStock ? (
        <button className="btn disabled" disabled>
          Unavailable
        </button>
      ) : quantity === 0 ? (
        <button className="btn add-btn" onClick={() => addToCart(item)}>
          ADD
        </button>
      ) : (
        <div className="qty-box">
          <button
            className="qty-btn"
            onClick={() => removeFromCart(item.id)}
          >
            −
          </button>

          <span className="qty">{quantity}</span>

          <button
            className="qty-btn"
            onClick={() => addToCart(item)}
            disabled={quantity >= item.stock}
          >
            +
          </button>
        </div>
      )}

    </div>
  );
}
